+/** Compares recipe use at sale time with all ledger consumption on the requested UTC days. */
+export function varianceReport(store, from, to) {
+  const totals = new Map();
+  function add(itemId, field, qty) {
+    if (!qty) return;
+    const line = totals.get(itemId) ?? { itemId, theoretical: 0, actual: 0 };
+    line[field] += Math.round(qty * 1000);
+    totals.set(itemId, line);
+  }
+  for (const sale of store.data.sales) {
+    const day = dayOf(sale.soldAt);
+    if (day >= from && day <= to)
+      for (const ingredient of sale.ingredients) add(ingredient.itemId, "theoretical", ingredient.qty);
+  }
+  const items = new Map(store.data.batches.map((batch) => [batch.id, batch.itemId]));
+  for (const movement of store.data.movements) {
+    if (movement.type !== "consume") continue;
+    const day = dayOf(movement.at);
+    if (day >= from && day <= to) add(items.get(movement.batchId), "actual", movement.qty);
+  }
+  return [...totals.values()].sort((a, b) => a.itemId - b.itemId).map(({ itemId, theoretical, actual }) => ({
+    itemId, theoretical: theoretical / 1000, actual: actual / 1000, variance: (actual - theoretical) / 1000,
+  }));
+}
