diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..1aea1a9
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,64 @@
+import { memoryStore } from "../db/store.js";
+import { isDate } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const columns = ["ticket", "soldAt", "dishId", "qty"];
+const csvLine = /^(?:"(?:[^"]|"")*"|[^",\r]*)(?:,(?:"(?:[^"]|"")*"|[^",\r]*))*$/;
+const instant = /^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-]\d{2}:\d{2})$/i;
+
+function invalid(row, reason) {
+  throw new AppError("bad_request", { reason: `row ${row}: ${reason}` });
+}
+
+/** Imports complete sales tickets atomically and counts the portions imported. */
+export function importSales(store, csv) {
+  if (typeof csv !== "string") invalid(1, "csv must be a string");
+  const staged = memoryStore(store.data);
+  const prior = new Set(staged.data.sales.map((sale) => sale.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  let header;
+  for (const [index, line] of csv.split(/\r?\n/).entries()) {
+    if (!line.trim()) continue;
+    const row = index + 1;
+    if (!csvLine.test(line)) invalid(row, "malformed CSV");
+    const fields = parseCsv(line)[0].map((field) => field.trim());
+    if (!header) {
+      if (fields.length !== columns.length || !columns.every((key) => fields.includes(key)))
+        invalid(row, "expected ticket,soldAt,dishId,qty");
+      header = fields;
+      continue;
+    }
+    if (fields.length !== header.length) invalid(row, "expected four fields");
+    const [ticket, soldAt, dish, count] = columns.map((key) => fields[header.indexOf(key)]);
+    if (!ticket) invalid(row, "missing ticket");
+    if (!instant.test(soldAt) || !Number.isFinite(Date.parse(soldAt)) || !isDate(soldAt.slice(0, 10)))
+      invalid(row, "invalid soldAt");
+    const dishId = Number(dish);
+    const qty = Number(count);
+    if (!/^\d+$/.test(dish) || !Number.isSafeInteger(dishId) || dishId < 1) invalid(row, "invalid dishId");
+    if (!/^\d+$/.test(count) || !Number.isSafeInteger(qty) || qty < 1) invalid(row, "invalid qty");
+    try {
+      const recipe = getRecipe(staged, getDish(staged, dishId).recipeId);
+      if (prior.has(ticket)) continue;
+      const at = new Date(soldAt).toISOString();
+      const ingredients = scaled(recipe, qty);
+      for (const ingredient of ingredients) {
+        if (ingredient.qty > 0) consume(staged, ingredient.itemId, ingredient.qty, { at, ref: `sale:${ticket}` });
+      }
+      staged.data.sales.push({ ticket, soldAt: at, dishId, qty, ingredients });
+      tickets.add(ticket);
+      dishes += qty;
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      invalid(row, error.params.item ? `insufficient stock of ${error.params.item}` : error.code);
+    }
+  }
+  if (!header) invalid(1, "missing header");
+  store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
